```tsx
import { useId } from "react";
import type { ReactElement } from "react";
import "./EmptyState.css";

export interface EmptyStateProps {
  title: string;
  message: string;
  actionLabel: string;
  onAction: () => void;
}

export function EmptyState({ title, message, actionLabel, onAction }: EmptyStateProps): ReactElement {
  const titleId = useId();
  return (
    <section className="empty-state" aria-labelledby={titleId}>
      <h2 id={titleId} className="empty-state__title">{title}</h2>
      <p className="empty-state__message">{message}</p>
      <button type="button" className="empty-state__action" onClick={onAction}>
        {actionLabel}
      </button>
    </section>
  );
}
```

