  min-height: 100%;
  padding: clamp(2rem, 6vw, 4rem) clamp(1rem, 4vw, 2rem);
  text-align: center;
  color: var(--ink);
}

.empty-state__title {
  margin: 0;
  font-size: clamp(1.25rem, 1rem + 1vw, 1.75rem);
