  color: var(--ink);
  text-wrap: balance;
}

.empty-state__message {
  margin: 0;
  max-width: 36ch;
  font-size: clamp(0.95rem, 0.9rem + 0.25vw, 1.1rem);
  line-height: 1.5;
  color: var(--muted);
  text-wrap: pretty;
}

.empty-state__action {
  margin-top: clamp(0.5rem, 1vw, 0.75rem);
